function gerarSenha(){var e=document.getElementById("length"),a=parseInt(e.value),t=document.getElementById("maiusculas").checked,n=document.getElementById("minusculas").checked,l=document.getElementById("numeros").checked,c=document.getElementById("simbolos").checked;let o="";if(t&&(o+="ABCDEFGHIJKLMNOPQRSTUVWXYZ"),n&&(o+="abcdefghijklmnopqrstuvwxyz"),l&&(o+="0123456789"),c&&(o+="!@#$%^&*()_+[]{}<>?/"),""===o)alert("Por favor, selecione pelo menos um tipo de caractere.");else if(isNaN(a)||a<8||16<a)alert("Digite um número entre 8 e 16 caracteres."),e.focus();else{let t="";for(let e=0;e<a;e++){var r=Math.floor(Math.random()*o.length);t+=o[r]}document.getElementById("resultado").value=t}}function copiarSenha(){var e=document.getElementById("resultado");""===e.value?alert("Nenhuma senha gerada para copiar!"):(e.select(),e.setSelectionRange(0,99999),document.execCommand("copy"),alert("Senha copiada com sucesso!"))}document.getElementById("length").addEventListener("input",function(e){var t=e.target.value;e.target.value=t.replace(/[^0-9]/g,""),2<e.target.value.length&&(e.target.value=e.target.value.slice(0,2))});